with flattened_attrs as (select id, plan, tier_prices, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, aggregate(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, slice(tier_limits, 1, 2) as first_two_limits, array_min(tier_prices) as lowest_price from price_tiers where plan != 'starter') select plan, count_if(plan = 'starter') as starter_events, sum(case when plan = 'enterprise' then avg_tier_price else 0 end) as enterprise_avg_tier_price, count(*) as row_count from flattened_attrs group by plan having starter_events > 1 order by plan desc nulls last
